      "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\">\n  <rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/>\n  <text x=\"550\" y=\"70\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"36\">KNOWLEDGE CHECK</text>\n  <text x=\"550\" y=\"115\" text-anchor=\"middle\" fill=\"#888\" font-size=\"24\">Test your understanding</text>\n  <rect x=\"150\" y=\"200\" width=\"800\" height=\"320\" rx=\"20\" fill=\"rgba(139,92,246,0.13)\" stroke=\"#8b5cf6\" stroke-width=\"2\"/>\n  <text x=\"550\" y=\"265\" text-anchor=\"middle\" fill=\"#8b5cf6\" font-weight=\"bold\" font-size=\"28\">TAXI DRIVERS</text>\n  <text x=\"550\" y=\"325\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"21\">Why did their</text>\n  <text x=\"550\" y=\"371\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"21\">hippocampi</text>\n  <text x=\"550\" y=\"417\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"21\">grow larger?</text>\n  <circle cx=\"550\" cy=\"660\" r=\"70\" fill=\"none\" stroke=\"#ffd700\" stroke-width=\"4\"/>\n  <text x=\"550\" y=\"680\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"48\">?</text>\n</svg>",
